// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // Put some Ether in the contract via the payable fallback.
        vm.deal(address(this), amount);
        address(c).call{value: amount}("");

        // Call withdrawAll as the owner.
        c.withdrawAll();

        // The reference sends the whole balance to the owner (which is address(this)),
        // so the contract's balance must be zero.
        // The mutant withdraw(0) leaves all funds in the contract.
        assertTrue(address(c).balance == 0);
    }

    receive() external payable {}
}
